from flask import Flask, request, jsonify
from functools import lru_cache
import os
from datetime import datetime

app = Flask(__name__)

# Data directory
DATA_DIR = "/workdir/data"

# Ensure data directory exists
os.makedirs(DATA_DIR, exist_ok=True)

# In-memory storage for queues
# Structure: {queue_name: {"messages": [{"id": int, "content": str, "timestamp": str}]}}
queues_storage = {}


@app.route("/status", methods=["GET"])
def status():
    """Return basic service status."""
    return jsonify({
        "status": "healthy",
        "queues": len(queues_storage)
    })


@app.route("/queues", methods=["POST"])
def create_queue():
    """Create new queue with JSON body: {"name": "queue_name"}.

    Returns: 201 Created with queue details
    """
    global queues_storage

    data = request.get_json()

    if not data or "name" not in data:
        return jsonify({"error": "Missing required field: name"}), 400

    queue_name = data["name"]

    # Validate queue name (basic check)
    if not queue_name or not isinstance(queue_name, str) or queue_name.strip() == "":
        return jsonify({"error": "Invalid queue name"}), 400

    # Store queue information
    queues_storage[queue_name] = {
        "messages": []
    }

    return jsonify({
        "message": "Queue created successfully",
        "queue_name": queue_name
    }), 201


@app.route("/queues/{queue_name}/messages", methods=["POST"])
def send_message(queue_name):
    """Send message with JSON body: {"content": "message"}.

    Returns: 201 Created with message details
    """
    global queues_storage

    # Route check - queue must exist
    if queue_name not in queues_storage:
        return jsonify({"error": "Queue not found"}), 404

    # Parse and validate request body
    data = request.get_json()

    if not data or "content" not in data:
        return jsonify({"error": "Missing required field: content"}), 400

    message_content = data["content"]

    if not message_content or not isinstance(message_content, str):
        return jsonify({"error": "Invalid message content"}), 400

    # Add message to queue (FIFO order)
    queue_data = queues_storage[queue_name]
    queue_data["messages"].append({
        "id": len(queue_data["messages"]),  # Unique message ID
        "content": message_content,
        "timestamp": datetime.utcnow().isoformat() + "Z"
    })

    return jsonify({
        "message": "Message sent successfully",
        "queue_name": queue_name,
        "message_id": len(queue_data["messages"])
    }), 201


@app.route("/queues/{queue_name}/messages", methods=["GET"])
def consume_message(queue_name):
    """Receive/consume one message from queue.

    Returns: 200 OK with consumed message OR 204 No Content if empty queue
    """
    global queues_storage

    # Route check - queue must exist
    if queue_name not in queues_storage:
        return jsonify({"error": "Queue not found"}), 404

    queue_data = queues_storage[queue_name]

    # Check if queue is empty
    if not queue_data["messages"]:
        return jsonify({"message": None, "error": "Queue is empty"}), 204

    # Get and remove the first message (FIFO)
    message = queue_data["messages"].pop(0)

    return jsonify({
        "message": {
            "id": message["id"],
            "content": message["content"],
            "timestamp": message["timestamp"]
        },
        "queue_name": queue_name
    }), 200


if __name__ == "__main__":
    # Start the server on port 8000
    app.run(host="0.0.0.0", port=8000)
